class LLMBaseModel(BaseModel):
    """
    Base model for LLM structured output with extra='forbid' configuration.

    This ensures that all fields are required and no extra fields are allowed,
    which is compatible with OpenAI's strict mode requirements.
    """

    model_config = ConfigDict(extra="forbid")


class LLMEvalBaseModel(LLMBaseModel):
    """
    Base model for LLM evaluation dimensions.

    Models inheriting from this class will automatically use non-strict mode
    in structured outputs because they typically use dict[str, T] patterns
    which are incompatible with strict mode's requirement for
    additionalProperties: false.
    """

    pass


def zero_to_ten(v: int) -> int:
    if v < 0 or v > 10:
        raise ValueError("The value should be between 0 and 10")
    return v


def minus_five_to_five(v: int) -> int:
    if v < -5 or v > 5:
        raise ValueError("The value should be between -5 and 5")
    return v


class PositiveReasoningScore(LLMBaseModel):
    reasoning: str = Field(..., description="Detailed reasoning for the evaluation")
    score: int = Field(
        ...,
        description="Score from 0 to 10, where higher scores indicate better performance",
    )

    @field_validator("score")
    @classmethod
    def validate_positive_score(cls, v: int) -> int:
        return zero_to_ten(v)


class BidirectionalReasoningScore(LLMBaseModel):
    reasoning: str = Field(..., description="Detailed reasoning for the evaluation")
    score: int = Field(
        ...,
        description="Score from -5 to 5, where higher scores indicate better performance",
    )

    @field_validator("score")
    @classmethod
    def validate_bidirectional_score(cls, v: int) -> int:
        return minus_five_to_five(v)


